    lines = input_str.strip().split('\n')
    if not lines:
        return "NO"

    n = int(lines[0])
    if n == 0:
        return "YES\n"
    a = list(map(int, lines[1].split()))

    # Try to assign each element to increasing (0) or decreasing (1)
    # Use greedy approach with backtracking/recursion for complex cases

    res = []
    # Track last values for both sequences
    last_inc = None  # last element in increasing sequence
    last_dec = None  # last element in decreasing sequence

    def solve(idx, last_inc, last_dec):
        if idx == n:
            return []

        current = a[idx]

        # Option 0: Assign to increasing sequence
        can_inc = False
        if last_inc is None:
            can_inc = True
        elif last_inc < current:
            can_inc = True

        # Option 1: Assign to decreasing sequence
        can_dec = False
        if last_dec is None:
            can_dec = True
        elif last_dec > current:
            can_dec = True

        if can_inc and can_dec:
            # Try both options
            # Greedy: prefer the one that gives more flexibility
            # If current == last_inc, can't really assign to increasing if strictly increasing
            # Unless it's the first element

            # Actually for strictly increasing:
            # can_inc means current > last_inc (or last_inc is None)
            # can_dec means current < last_dec (or last_dec is None)

            if can_inc:
                # Try assigning to increasing first
                new_res = solve(idx + 1, current, last_dec)
                if new_res is not None:
                    res.append(0)
                    return new_res

            if can_dec:
                # Try assigning to decreasing
                new_res = solve(idx + 1, last_inc, current)
                if new_res is not None:
                    res.append(1)
                    return new_res

        elif can_inc:
            res.append(0)
            return solve(idx + 1, current, last_dec)

        elif can_dec:
            res.append(1)
            return solve(idx + 1, last_inc, current)

        return None

    result = solve(0, None, None)
    if result is not None:
