def solution(input_string):
    if not input_string.strip():
        return ""

    lines = input_string.strip().split('\n')
    n_k = lines[0].split()
    n = int(n_k[0])
    k = int(n_k[1])

    a = list(map(int, lines[1].split()))

    memo = {}

    def grundy(val):
        if val == 0:
            return 0
        if val in memo:
            return memo[val]

        moves = set()
        # Move 1: Remove one cow
        moves.add(grundy(val - 1))

        # Move 2: Split even size pile into k piles of half the size
        if val % 2 == 0:
            x = val // 2
            gx = grundy(x)
            if k % 2 == 0:
                # Even k: gx XOR gx XOR ... (k times) = 0
                moves.add(0)
            else:
                # Odd k: gx XOR gx XOR ... (k times) = gx
                moves.add(gx)

        # Calculate mex (minimum excludant)
        mex = 0
        while mex in moves:
            mex += 1

        memo[val] = mex
        return mex

    # Calculate XOR sum of Grundy numbers
    xor_sum = 0
    for x in a:
        xor_sum ^= grundy(x)

    if xor_sum > 0:
        return "Kevin\n"
    else:
        return "Nicky\n"

