                            valid = False
                            break
                    if not valid:
                        continue

                    # Left and right columns
                    for rr in range(r, r + size):
                        if grid[rr][c] == '0' or grid[rr][c + size - 1] == '0':
                            valid = False
                            break
                    if not valid:
                        continue

                    # Check no foreign 1s touching (by side or corner)
                    # Check area just outside the square
                    for dr in [-1, 0, 1]:
                        for dc in [-1, 0, 1]:
                            if dr == 0 and dc == 0:
                                continue
                            r2, c2 = r + dr, c + dc
                            if r2 < r or r2 >= r + size or c2 < c or c2 >= c + size:
                                if 0 <= r2 < n and 0 <= c2 < m:
                                    if grid[r2][c2] == '1':
                                        valid = False
                                        break
                        if not valid:
                            break
                    if not valid:
                        continue

                    # Valid square found
                    count += 1

        # Check diagonal squares
        for d1 in range(2, max_size + 1):
            for d2 in range(2, max_size + 1):
                # Diagonal square with top-left corner at (r, c)
                for r in range(2, n - d1):
                    for c in range(2, m - d2):
                        # Top-left corner
                        if grid[r][c] == '0':
                            continue
                        # Top-right corner
                        if grid[r][c + d1] == '0':
                            continue
                        # Bottom-left corner
                        if grid[r + d2][c] == '0':
                            continue
                        # Bottom-right corner
                        if grid[r + d2][c + d1] == '0':
                            continue

                        # Check left edge (diagonal from (r,c) to (r+d2, c+d1-free))
                        for i in range(1, d2):
                            if grid[r + i][c + i] == '0':
                                break
                        else:
                            continue

                        # Check right edge
                        for i in range(1, d2):
                            if grid[r + i][c + d1 - i] == '0':
                                break
                        else:
                            continue

                        # Check top edge (diagonal from (r,c) to (r+d1, c))
                        for i in range(1, d1):
                            if grid[r + i][c] == '0':
                                break
                        else:
                            continue

                        # Check bottom edge
                        for i in range(1, d1):
                            if grid[r + d2][c - i] == '0':
                                break
                        else:
                            continue

                        # Check no foreign 1s touching
                        valid = True
                        for dr in range(-2, 3):
                            for dc in range(-2, 3):
                                r2, c2 = r + dr, c + dc
                                if r2 < 0 or r2 >= n or c2 < 0 or c2 >= m:
                                    continue
                                if 0 <= r2 < n and 0 <= c2 < m:
                                    if grid[r2][c2] == '1':
                                        # Check if this 1 is part of a corner or edge of the diagonal square
                                        is_edge = False
                                        if abs(dr) <= 1 and abs(dc) <= 1:  # Close to corners
                                            is_edge = True
                                        # Check if on the diagonal edge
                                        if not is_edge:
                                            valid = False
                                            break
                            if not valid:
