import sys

class Dinic:
    def __init__(self, n):
        self.n = n
        self.graph = [[] for _ in range(n)]
        self.level = []

    def add_edge(self, u, v, capacity, edge_index=-1):
        self.graph[u].append([v, capacity, len(self.graph[v]), edge_index])
        self.graph[v].append([u, 0, len(self.graph[u]) - 1, -1])

    def bfs(self, s, t):
        self.level = [-1] * self.n
        self.level[s] = 0
        queue = deque([s])
        while queue:
            u = queue.popleft()
            for v, cap, rev, _ in self.graph[u]:
                if cap > 0 and self.level[v] < 0:
                    self.level[v] = self.level[u] + 1
                    queue.append(v)
        return self.level[t] >= 0

    def dfs(self, u, t, flow, ptr):
        if u == t or flow == 0:
            return flow
        for i in range(ptr[u], len(self.graph[u])):
            ptr[u] = i
            v, cap, rev, edge_idx = self.graph[u][i]
            if self.level[v] == self.level[u] + 1 and cap > 0:
                pushed = self.dfs(v, t, min(flow, cap), ptr)
                if pushed > 0:
                    self.graph[u][i][1] -= pushed
                    self.graph[v][rev][1] += pushed
                    return pushed
        return 0

    def max_flow(self, s, t, track_flows=None):
        if track_flows is None:
            track_flows = set()
        max_f = 0
        while self.bfs(s, t):
            ptr = [0] * self.n
            path_edges = []
            while True:
                pushed = self.dfs(s, t, float('inf'), ptr)
                if pushed == 0:
                    break
                max_f += pushed
                if max_f >= pushed * 100:  # Limit iterations
                    break
        # Find edges that carried flow (forward edges with capacity decreased)
        for u in range(self.n):
            for i, (v, cap, rev, edge_idx) in enumerate(self.graph[u]):
                if edge_idx > -1 and cap == 0:
                    track_flows.add(edge_idx)
        return max_f

