    grid = [['.' for _ in range(m)] for _ in range(n)]

    # Define 4 T-rotations
    # Each shape is given as relative offsets (dr, dc) from the top-left corner
    SHAPES = [
        [(0, 0), (0, 1), (0, 2), (1, 1), (2, 1)],  # T pointing down
        [(0, 1), (1, 0), (1, 1), (1, 2), (2, 1)],  # T pointing right
        [(0, 1), (1, 0), (1, 1), (1, 2), (0, 0)],  # T pointing up
        [(0, 1), (1, 1), (1, 2), (0, 0), (0, 2)]   # T pointing left
    ]

    placed_count = 0
    best_count = 0
    best_grid = [row[:] for row in grid]

    def can_place(shape, r, c):
        for dr, dc in shape:
            nr, nc = r + dr, c + dc
            if nr < 0 or nr >= n or nc < 0 or nc >= m or grid[nr][nc] != '.':
                return False
        return True

    def place_shape(shape, r, c, char):
        for dr, dc in shape:
            grid[r + dr][c + dc] = char

    def remove_shape(shape, r, c):
        for dr, dc in shape:
            grid[r + dr][c + dc] = '.'

    def dfs():
        nonlocal placed_count, best_count, best_grid

        # Find first empty cell
        for r in range(n):
            for c in range(m):
                if grid[r][c] == '.':
                    # Try placing all 4 rotations at this position
                    for shape in SHAPES:
                        if can_place(shape, r, c):
                            # Place shape
                            for dr, dc in shape:
                                grid[r + dr][c + dc] = chr(ord('A') + placed_count)

                            # Recurse
                            dfs()

                            # Backtrack - remove shape
                            for dr, dc in shape:
                                grid[r + dr][c + dc] = '.'

                    # Try moving to next cell (don't place at current)
                    break
            else:
                continue
            break

        # No empty cells found - record best solution
        if placed_count > best_count:
            best_count = placed_count
            best_grid = [row[:] for row in grid]

    dfs()

    # Format output
    result_lines = [str(best_count)]
    for row in best_grid:
        result_lines.append(''.join(row))
