from collections import defaultdict

def solution(input_str):
    data = input_str.strip().split('\n')
    parts = data[0].split()
    N, M, K = int(parts[0]), int(parts[1]), int(parts[2])

    # Parse transformers
    # Each transformer: x y d t e
    transformers = []
    for i in range(1, K + 1):
        line = data[i].split()
        x, y, d, t, e = int(line[0]), int(line[1]), int(line[2]), int(line[3]), int(line[4])
        transformers.append((x, y, d, t, e))

    # For each cell, compute the total kill energy of transformers present
    # cost[r][c] = total energy needed if we're at (r,c) at time r+c
    cost = [[0] * M for _ in range(N)]

    for r in range(N):
        for c in range(M):
            time = r + c
            total_energy = 0

            for tx, ty, td, tt, te in transformers:
                if time < tt:
                    continue  # Transformer hasn't started yet

                offset = (time - tt) % 4

                # Get transformer position at this offset in cycle
                if offset == 0:
                    r_t, c_t = tx, ty
                elif offset == 1:
                    r_t, c_t = tx + td, ty - td
                elif offset == 2:
                    r_t, c_t = tx + td, ty
                else:  # offset == 3
                    r_t, c_t = tx, ty + td

                if r_t == r and c_t == c:
                    total_energy += te

            cost[r][c] = total_energy

    # DP: minimum energy to reach each cell from (0,0)
    INF = float('inf')
    dp = [[INF] * M for _ in range(N)]

    dp[0][0] = cost[0][0]

    for r in range(N):
        for c in range(M):
            if r > 0:
                if dp[r-1][c] != INF:
                    dp[r][c] = min(dp[r][c], dp[r-1][c] + cost[r][c])
            if c > 0:
                if dp[r][c-1] != INF:
                    dp[r][c] = min(dp[r][c], dp[r][c-1] + cost[r][c])

    return str(dp[N-1][M-1]) + '\n'

