    cards = []

    for i in range(1, 2*n + 1):
        a, b = map(int, lines[i].split())
        cards.append((a, b))

    def is_balanced(seq):
        stack = []
        for x in seq:
            if x > 0:
                stack.append(x)
            else:
                if not stack or stack[-1] != abs(x):
                    return False
                stack.pop()
        return len(stack) == 0

    # Try sorting strategies
    best_perm = None

    # Strategy 1: Try sorted by (abs(a), a, b)
    for sort_key in [(lambda c: abs(c[0])), (lambda c: (abs(c[0]), c[0], c[1]))]:
        for perm in permutations(cards):
            front = [c[0] for c in perm]
            back = [c[1] for c in perm]
            if is_balanced(front) and is_balanced(back):
                best_perm = list(perm)
                break
        if best_perm:
            break

    # If not found yet, try runtime limit with greedy
    if not best_perm:
        for perm in permutations(cards):
            front = [c[0] for c in perm]
            back = [c[1] for c in perm]
            if is_balanced(front) and is_balanced(back):
                best_perm = list(perm)
                break

    if best_perm:
        output = ["YES"]
        for a, b in best_perm:
            output.append(f"{a} {b}")
        return '\n'.join(output) + '\n'

    return "NO\n"


