            current_dp = {}

            # From (i-1, j): added 1
            if i > 0:
                for max_k, count in dp[i-1][j].items():
                    new_current = max_k + 1  # current becomes max when we add 1
                    current_dp[max_k] = (current_dp.get(max_k, 0) + count) % MOD

            # From (i, j-1): added -1
            if j > 0:
                for max_k, count in dp[i][j-1].items():
                    new_current = max_k - 1
                    current_dp[max_k] = (current_dp.get(max_k, 0) + count) % MOD

            dp[i][j] = current_dp

    # Compute answer
    ans = 0
    for i in range(n + 1):
