    def check_bitonic(arr, length):
        """Check if array is bitonic (increases then decreases)."""
        if length <= 1:
            return True
        peak = 0
        # Find peak position
        for i in range(1, length):
            if arr[i] > arr[peak]:
                peak = i
        # Check increasing part (before peak)
        for i in range(peak - 1, -1, -1):
            if arr[i] >= arr[i + 1]:
                return False
        # Check decreasing part (after peak)
        for i in range(peak + 1, length):
            if arr[i] >= arr[i - 1]:
                return False
        return True

    def check_valid(result):
        # Check all rows are bitonic
        for i in range(n):
