        matrix.append(row)

    def count_factor(num, factor):
        count = 0
        while num > 0 and num % factor == 0:
            num //= factor
            count += 1
        return count

    # Precompute factor counts for 2 and 5 for each cell
    factor_counts = [[0]*n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            factor_counts[i][j] = (count_factor(matrix[i][j], 2), count_factor(matrix[i][j], 5))

    # dp[i][j] = dict mapping (cnt2, cnt5) -> tuple(parent_t2, parent_t5, move)
    # We store Pareto-optimal pairs: (cnt2, cnt5) where no other pair has <= both values
    dp = [{} for _ in range(n)]
    for j in range(n):
        dp[0][j] = {}

    for i in range(n):
        for j in range(n):
            dp[i][j] = {}

    # Base case at (0,0)
    c2, c5 = factor_counts[0][0]
    dp[0][0][(c2, c5)] = (-1, -1, '')

    # Fill DP table
    for i in range(n):
        for j in range(n):
            if i == 0 and j == 0:
                continue

            c2, c5 = factor_counts[i][j]

            # Try coming from above (direction 'D')
            if i > 0:
                for (prev_t2, prev_t5), parent_info in dp[i-1][j].items():
                    new_t2 = prev_t2 + c2
                    new_t5 = prev_t5 + c5
                    if (new_t2, new_t5) not in dp[i][j]:
                        dp[i][j][(new_t2, new_t5)] = (prev_t2, prev_t5, 'D')

            # Try coming from left (direction 'R')
            if j > 0:
                for (prev_t2, prev_t5), parent_info in dp[i][j-1].items():
                    new_t2 = prev_t2 + c2
                    new_t5 = prev_t5 + c5
                    if (new_t2, new_t5) not in dp[i][j]:
                        dp[i][j][(new_t2, new_t5)] = (prev_t2, prev_t5, 'R')

    # Find Pareto-optimal pairs at (n-1, n-1)
    final_pairs = list(dp[n-1][n-1].keys())
    optimal_final = []

    for (t2, t5) in final_pairs:
        dominated = False
        for (other_t2, other_t5) in final_pairs:
            if other_t2 <= t2 and other_t5 <= t5:
                dominated = True
                break
        if not dominated:
            optimal_final.append((t2, t5))

    # Find minimum trailing zeros
    min_zeros = min(min(t2, t5) for (t2, t5) in optimal_final)

    # Reconstruct path
    # Choose first non-dominated pair with min trailing zeros
    best_t2, best_t5 = None, None
    for (t2, t5) in optimal_final:
        if min(t2, t5) == min_zeros:
            best_t2, best_t5 = t2, t5
            break

    path = []
    cur_t2, cur_t5 = best_t2, best_t5
    i, j = n - 1, n - 1

    while i > 0 or j > 0:
        parent_info = dp[i][j][(cur_t2, cur_t5)]
        prev_t2, prev_t5, move = parent_info
        path.append(move)
        cur_t2, cur_t5 = prev_t2, prev_t5
        if move == 'D':
            i -= 1
        else:
            j -= 1

    path.reverse()

    return f"{min_zeros}\n{''.join(path)}"

