MOD = 10**9 + 7

def solution(input_str):
    s = input_str.strip()
    n = len(s)
    pos = 0

    def parse_expression():
        nonlocal pos
        left_val, left_len = parse_term()
        while pos < n and s[pos] == '+':
            pos += 1
            right_val, right_len = parse_term()
            # Concatenate: left * 10^right_len + right
            left_val = (left_val * pow(10, right_len, MOD) + right_val) % MOD
            left_len += right_len
        return left_val, left_len

    def parse_term():
        nonlocal pos
        if s[pos] == '(':
            pos += 1  # consume '('
            expr_val, expr_len = parse_expression()
            pos += 1  # consume ')'
            # Repeat expression
            count = parse_number()
            return repeat_expr(count, expr_val, expr_len)
        else:
            num = parse_number()
            if pos < n and s[pos] == '-':
                pos += 1
                num2 = parse_number()
                return range_concat(num, num2)
            return num, len(str(num))

    def parse_number():
        nonlocal pos
        start = pos
        while pos < n and s[pos].isdigit():
            pos += 1
        return int(s[start:pos])

    def range_concat(l, r):
        """Concatenate all numbers from l to r"""
        result = 0
        total_digits = 0
        for i in range(l, r + 1):
            s_i = str(i)
            result = (result * pow(10, len(s_i), MOD) + i) % MOD
            total_digits += len(s_i)
        return result, total_digits

    def repeat_expr(count, expr_val, expr_len):
        """Concatenate expr_val, count times"""
        result = 0
        for i in range(count):
            result = (result * pow(10, expr_len, MOD) + expr_val) % MOD
        return result, expr_len * count

    # Parse and compute the result
    result, _ = parse_expression()
    return str(result)


