from collections import deque

def solution(n_str):
    n = int(n_str.strip())

    if n == 0:
        return "0"

    # BFS with memoization to find minimum operations
    # Key insight: BFS guarantees finding the shortest path
    visited = {n: 0}
    queue = deque([n])

    while queue:
        current = queue.popleft()
        current_steps = visited[current]

        if current == 0:
            return str(current_steps)

        # Get unique non-zero digits from current number
        digits = set(str(current)) - {'0'}

        for d in digits:
            next_val = current - int(d)
            if next_val not in visited:
                visited[next_val] = current_steps + 1
                queue.append(next_val)

    return "0"  # Should not reach here for valid input

